WITH valid AS (SELECT id, name, email, country, city, segment, is_active, credit_limit, age, credit_limit + age AS credit_limit_plus_age, UPPER(country) AS country_upper, COALESCE(segment, 'NONE') AS segment_clean FROM customers WHERE LENGTH(email) >= 13), latest AS (SELECT id, country, segment, age, segment_clean FROM valid QUALIFY RANK() OVER (PARTITION BY city ORDER BY credit_limit DESC) = 1), latest_match AS (SELECT s.*, latest.started_at FROM latest s JOIN LATERAL (SELECT c.started_at FROM sessions c WHERE c.customer_id = s.id ORDER BY c.started_at DESC, c.id DESC LIMIT 1) latest ON TRUE), not_flagged AS (SELECT s.* FROM latest_match s WHERE NOT EXISTS (SELECT 1 FROM orders ch WHERE ch.customer_id = s.id AND ch.customer_id IS NOT NULL)), cleaned AS (SELECT id, country, segment, age, segment_clean, started_at, COALESCE(segment, 'unassigned') AS segment_filled, SUBSTRING(country, 1, 4) AS country_prefix FROM not_flagged WHERE segment IS NOT NULL), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY segment ORDER BY age NULLS LAST, id) AS rn FROM cleaned QUALIFY rn = 1) SELECT CASE WHEN age >= 72 THEN 'HIGH' ELSE 'LOW' END AS age_tier, APPROX_PERCENTILE(age, 0.9) AS age_p90, ROUND(AVG(age), 2) AS avg_age FROM ranked GROUP BY CASE WHEN age >= 72 THEN 'HIGH' ELSE 'LOW' END
